"""Ferrari team portal and partner intake, preserving the approved site shell."""
from pathlib import Path
from html import escape
import json,shutil

def build_team_pages(out,head,header,footer,props,wa,absolute_assets):
    manifest=json.loads(Path('team-materials.json').read_text());files={p['id']:p['files'] for p in manifest['properties']}
    def page(path,title,description,body,script='site-tools.js',private=False):
        h=head(title,description,path,'tools')
        if private:h=h.replace('index, follow, max-image-preview:large','noindex, follow')
        h=h.replace('</head>',f'<script src="/{script}" defer></script></head>')
        p=out/path.strip('/');p.mkdir(parents=True,exist_ok=True)
        (p/'index.html').write_text(absolute_assets('<!doctype html><html lang="pt-BR">'+h+'<body><a class="skip" href="#inicio">Pular para o conteúdo</a>'+header+body+footer+'</body></html>'))
    reference_label=manifest['label'];short_reference=manifest['reference'][-2:]+'/'+manifest['reference'][:4];received_label='/'.join(reversed(manifest['received'].split('-')))
    cards=[]
    for p in props:
        items=files.get(p['id'],{});links=p['links'];book=items.get('book');table=items.get('tabela')
        def link(url,label,icon='file',download=False):
            return f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer" {"download" if download else ""}><i data-icon="{icon}"></i>{escape(label)}</a>'
        book_link=link(book['url'],f"Book em PDF · {book['bytes']/1048576:.1f} MB",download=True) if book else link(links['book'],'Book do empreendimento') if links.get('book') else link(wa('Olá! Gostaria de receber o book do '+p['name']+'.'),'Solicitar book','whatsapp')
        table_link=link(table['url'],'Tabela de referência · out/2026',download=True) if table else ''
        tour=link(links['tour'],'Tour virtual','play') if links.get('tour') else ''
        cards.append(f'''<article class="material-card" data-material-name="{escape(p['name']+' '+p['neighborhood']+' '+p['regionLabel'],quote=True)}" data-material-region="{p['region']}"><img src="/{p['image']}" alt="{p['name']}, perspectiva ilustrativa" width="700" height="440" loading="lazy" decoding="async"><div><p class="eyebrow">{p['regionLabel']} · {p['neighborhood']}</p><h2>{p['name']}</h2><p>{' e '.join(map(str,p['beds']))} dormitórios · {p['area']} m²</p><div class="resource-links">{link('/imoveis/'+p['id']+'/','Ficha e imagens','home')}{book_link}{tour}{table_link}</div><p class="material-reference">{'Materiais recebidos em 30/10/2026. Tabela de referência: outubro/2026.' if table else 'Tabela local ainda não recebida. Consulte a equipe.'}</p><button class="text-link" data-copy-property="{p['id']}" data-title="{p['name']}">Copiar link para o cliente <i data-icon="share"></i></button><a class="text-link material-help" href="{wa('Olá! Preciso confirmar a tabela vigente e as condições do '+p['name']+'.')}" target="_blank" rel="noopener noreferrer">Confirmar condições <i data-icon="arrow-up-right"></i></a></div></article>''')
    body='''<main id="inicio" class="wrap tools-page team-page"><nav class="breadcrumbs" aria-label="Caminho de navegação"><a href="/">Início</a><span>/</span><span aria-current="page">Equipe Ferrari</span></nav><section class="team-hero"><div><p class="eyebrow"><span></span> CENTRAL DA EQUIPE FERRARI</p><h1>Tudo à mão.<br>Mais tempo para vender.</h1><p>Books, tabelas e apresentações em um só lugar. Encontre o empreendimento, consulte os materiais e compartilhe a ficha com seu cliente.</p><a class="btn btn-dark" href="#biblioteca">Acessar os materiais <i data-icon="arrow-down"></i></a></div><div class="team-identity"><img src="/assets/ferrari-logo.png" alt="Equipe Ferrari" width="100" height="107"><span>ASSESSORIA IMOBILIÁRIA</span><strong>Ética. Confiança.<br>Resultados.</strong><p>São Paulo &amp; Jundiaí</p></div></section><div class="team-facts"><span><strong>14</strong> empreendimentos</span><span><strong>13</strong> books para baixar</span><span><strong>Out/2026</strong> referência das tabelas</span></div><section id="biblioteca" aria-labelledby="library-title"><div class="section-top"><div><p class="eyebrow"><span></span> BIBLIOTECA COMERCIAL</p><h2 id="library-title">A informação certa.<br><span>No seu próximo atendimento.</span></h2></div><p class="section-description">Confira a referência de cada documento. Preços, estoque e promoções devem ser validados antes de apresentar uma proposta.</p></div><div class="materials-toolbar"><label class="catalog-search"><i data-icon="search"></i><input type="search" id="material-search" aria-label="Buscar materiais por empreendimento ou bairro" placeholder="Empreendimento ou bairro" maxlength="120"></label><label class="form-field"><span>Região</span><select id="material-region"><option value="all">Todas as regiões</option><option value="sul">Zona Sul</option><option value="leste">Zona Leste</option><option value="oeste">Zona Oeste</option><option value="norte">Zona Norte</option><option value="jundiai">Jundiaí</option></select></label></div><p id="material-count" role="status" aria-live="polite">14 empreendimentos</p><div class="materials-grid">'''+''.join(cards)+'''</div><p id="material-empty" class="empty-state" hidden>Nenhum material com essa busca. Experimente outro bairro ou região.</p></section><aside class="materials-note"><i data-icon="file"></i><p><strong>Virou o mês? Confira a nova tabela.</strong> Os arquivos desta edição têm referência de outubro/2026. A data de recebimento não garante a vigência comercial. Confirme a versão mais recente com a equipe.</p></aside><section class="team-partner-banner"><div><p class="eyebrow"><span></span> IMOBILIÁRIAS PARCEIRAS</p><h2>Vamos construir<br><span>novas possibilidades.</span></h2><p>Conheça o cadastro de parceria e as etapas para apresentar sua imobiliária à Equipe Ferrari.</p></div><a class="btn btn-dark" href="/parcerias/">Conhecer o cadastro <i data-icon="arrow-right"></i></a></section><div id="toast" class="toast" role="status" aria-live="polite"></div></main>'''
    body=body.replace('Out/2026',short_reference).replace('out/2026',short_reference).replace('outubro/2026',reference_label.lower()).replace('30/10/2026',received_label).replace('<strong>13</strong>',f'<strong>{len(files)}</strong>').replace('<strong>14</strong>',f'<strong>{len(props)}</strong>')
    page('/equipe/','Central da Equipe Ferrari | Books, tabelas e materiais','Central da Equipe Ferrari: books em PDF, tabelas de referência, tours e fichas para compartilhar. Materiais comerciais organizados por empreendimento e região.',body)
    def field(id,label,type='text',required=True,autocomplete='off',extra=''):
        return f'<label class="form-field" for="partner-{id}"><span>{label}{" *" if required else " · opcional"}</span><input id="partner-{id}" name="{id}" type="{type}" {"required" if required else ""} maxlength="{200 if type=="email" else 150}" autocomplete="{autocomplete}" {extra}></label>'
    company=field('razaoSocial','Razão social',autocomplete='organization')+field('nomeFantasia','Nome fantasia',required=False)+field('cnpj','CNPJ',extra='placeholder="00.000.000/0001-00"')+field('creci','CRECI da imobiliária')+field('cidade','Cidade / UF')+field('site','Site ou perfil profissional',required=False)
    contact=field('responsavel','Nome do responsável',autocomplete='name')+field('cargo','Cargo ou vínculo com a imobiliária',required=False)+field('email','E-mail para contato','email',autocomplete='email')+field('whatsapp','WhatsApp','tel',autocomplete='tel')
    documents=''.join(f'<label class="form-field document-field" for="document-{id}"><span>{label} <small>Lista preliminar</small></span><input id="document-{id}" type="file" data-document="{id}" accept=".pdf,.jpg,.jpeg,.png" disabled><small>PDF, JPG ou PNG · até 2 MB por arquivo</small></label>' for id,label in [('cnpj','Cartão CNPJ'),('contrato','Contrato social ou documento equivalente'),('creci','Comprovante de CRECI da imobiliária'),('complemento','Documentação complementar solicitada pela equipe')])
    body=f'''<main id="inicio" class="wrap tools-page partnership-page"><nav class="breadcrumbs" aria-label="Caminho de navegação"><a href="/">Início</a><span>/</span><span aria-current="page">Imobiliárias parceiras</span></nav><div class="planning-layout"><div class="planning-intro"><p class="eyebrow"><span></span> PARCERIAS COM IMOBILIÁRIAS</p><h1>Mais conexões.<br>Novas possibilidades.</h1><p>Apresente sua imobiliária à Equipe Ferrari. O cadastro reúne as informações da empresa, o contato do responsável e a documentação solicitada.</p><ol class="planning-benefits"><li><strong>Identifique a imobiliária</strong>Informe os dados da empresa e de quem representa a parceria.</li><li><strong>Reúna os documentos</strong>Confira os arquivos solicitados antes de enviar.</li><li><strong>Acompanhe o recebimento</strong>Guarde o protocolo exibido ao concluir o cadastro.</li></ol><a class="text-link" href="{wa('Olá! Quero informações sobre parceria da minha imobiliária com a Equipe Ferrari.')}" target="_blank" rel="noopener noreferrer">Conversar sobre parceria <i data-icon="arrow-up-right"></i></a><p class="form-note">O envio de um cadastro não representa aprovação automática da parceria.</p></div><div class="planning-card partner-card"><div class="intake-status" id="intake-status" role="status"><strong>Cadastro em preparação</strong><p>O envio de documentos ainda não foi ativado. A lista documental e o recebimento por e-mail estão em configuração.</p></div><noscript><p>Ative o JavaScript para consultar a disponibilidade do cadastro ou fale com a equipe pelo WhatsApp.</p></noscript><div class="form-progress" aria-label="Etapas do cadastro"><span data-partner-indicator="0" aria-current="step">1. Imobiliária</span><span data-partner-indicator="1">2. Responsável</span><span data-partner-indicator="2">3. Documentos</span><span data-partner-indicator="3">4. Revisão</span></div><form id="partner-form" autocomplete="off"><div class="form-honeypot" aria-hidden="true"><label>Website de confirmação<input type="text" name="website" tabindex="-1" autocomplete="off"></label></div><fieldset id="partner-fields" disabled><section data-partner-step="0"><h2 tabindex="-1">Dados da imobiliária</h2><div class="form-grid">{company}</div><button type="button" class="btn btn-red" data-partner-next>Continuar <i data-icon="arrow-right"></i></button></section><section data-partner-step="1" hidden><h2 tabindex="-1">Quem representa a parceria?</h2>{contact}<div class="form-actions"><button type="button" class="text-btn" data-partner-back>Voltar</button><button type="button" class="btn btn-red" data-partner-next>Continuar <i data-icon="arrow-right"></i></button></div></section><section data-partner-step="2" hidden><h2 tabindex="-1">Documentação da imobiliária</h2><p class="form-note">Envie somente os documentos solicitados. Confira se o arquivo está legível e contém todas as páginas necessárias.</p><div id="partner-documents">{documents}</div><div class="form-actions"><button type="button" class="text-btn" data-partner-back>Voltar</button><button type="button" class="btn btn-red" data-partner-next>Revisar cadastro <i data-icon="arrow-right"></i></button></div></section><section data-partner-step="3" hidden><h2 tabindex="-1">Confira antes de enviar.</h2><dl id="partner-review" class="partner-review"></dl><label class="partner-consent"><input type="checkbox" name="consent" required><span>Confirmo que represento a imobiliária e autorizo o uso dos dados e documentos enviados para análise deste cadastro e contato sobre a parceria. <a href="/privacidade/" target="_blank" rel="noopener noreferrer">Conhecer a privacidade.</a></span></label><div class="form-actions"><button type="button" class="text-btn" data-partner-back>Ajustar cadastro</button><button type="submit" class="btn btn-red" id="partner-submit">Enviar cadastro <i data-icon="arrow-right"></i></button></div></section></fieldset><p id="partner-error" class="form-error" role="alert" hidden></p><div id="partner-upload-progress" class="upload-progress" role="status" aria-live="polite" hidden></div></form><section id="partner-success" hidden tabindex="-1"><p class="eyebrow"><span></span> CADASTRO RECEBIDO</p><h2>Obrigado por se apresentar.</h2><p id="partner-success-message"></p><p>Protocolo: <strong id="partner-protocol"></strong></p><a class="btn btn-dark" href="/equipe/">Conhecer a central da equipe <i data-icon="arrow-right"></i></a></section><details class="partner-preview"><summary>Conheça as etapas e a documentação prevista</summary><p>O cadastro terá dados da imobiliária, contato do responsável, envio de arquivos e revisão final. A documentação prevista inclui cartão CNPJ, contrato social ou documento equivalente e comprovante de CRECI. A lista definitiva será confirmada pela Equipe Ferrari antes da ativação.</p></details></div></div></main>'''
    page('/parcerias/','Cadastro de imobiliárias parceiras | Equipe Ferrari','Conheça o cadastro de imobiliárias parceiras da Equipe Ferrari: dados da empresa, contato do responsável e documentação para análise da parceria.',body,'partnership.js',True)
    # The old route is retained as a host-level 308 redirect, never as a duplicate indexable page.
    old=out/'materiais'
    if old.is_dir():shutil.rmtree(old)
